        if (num == 0) return 0;
        if (k == 0) return num % 10 == 0 ? 1 : -1;
        int g = __gcd(k, 10);
        if (num % g) return -1;
        int mod = 10 / g, kk = (k / g) % mod;
        int inv = 1;
        for (int x = 1; x < mod; x++) if (kk * x % mod == 1) { inv = x; break; }
