class Solution {
    public int minimumNumbers(int num, int k) {
        if (num == 0) return 0;
        if (k == 0) return num % 10 == 0 ? 1 : -1;
        int g = gcd(k, 10);
        if (num % g != 0) return -1;
        int mod = 10 / g, kk = (k / g) % mod, inv = 1;
        for (int x = 1; x < mod; x++) if (kk * x % mod == 1) { inv = x; break; }
        int t = (int)((long)(num / g % mod) * inv % mod);
        if (t == 0) t = mod;
        return (long) t * k <= num ? t : -1;
    }
    private int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
}

