var minimumNumbers = function(num, k) {
    if (num === 0) return 0;
    if (k === 0) return num % 10 === 0 ? 1 : -1;
    const g = (a, b) => b ? g(b, a % b) : a;
    const d = g(k, 10);
    if (num % d) return -1;
    const mod = 10 / d, kk = (k / d) % mod;
    let inv = 1;
    for (let x = 1; x < mod; x++) if (kk * x % mod === 1) { inv = x; break; }
    let t = (Math.floor(num / d) % mod) * inv % mod;
    if (t === 0) t = mod;
    return t * k <= num ? t : -1;
};
